export class User {
    displayName?: string;
    username?: string;
    id?: string | number;
    firstName?: string;
    lastName?: string;
    email?: string;
    createdTimestamp?: any;
    emailVerified?: boolean;
    enabled?: boolean;
    readonly?: boolean;
    pictureId?: number;
    avatarId: string;

    constructor(user?: Partial<User>) {
        if (user) {
            Object.assign(this, user);
        }
    }
}
