import { effect, Injectable, InjectionToken, inject } from '@angular/core';
import { TranslateService } from '@ngx-translate/core';
import { Observable } from 'rxjs';
import { TranslateLoaderService } from './translate-loader.service';
import { UserPreferencesService, UserPreferenceValues } from '../common/services/user-preferences.service';

export const TRANSLATION_PROVIDER = new InjectionToken('Injection token for translation providers.');

export interface TranslationProvider {
    name: string;
    source: string;
}

/**
 * Generate translation provider
 *
 * @param id Unique identifier
 * @param path Path to translation files
 * @returns Provider
 */
export function provideTranslations(id: string, path: string) {
    return {
        provide: TRANSLATION_PROVIDER,
        multi: true,
        useValue: {
            name: id,
            source: path
        }
    };
}

@Injectable({
    providedIn: 'root'
})
export class TranslationService {
    translate = inject(TranslateService);
    private readonly userPreferencesService = inject(UserPreferencesService);
    private readonly providers = inject<TranslationProvider[]>(TRANSLATION_PROVIDER, { optional: true }) ?? [];

    defaultLang: string;
    userLang: string;
    customLoader: TranslateLoaderService;

    constructor() {
        this.customLoader = this.translate.currentLoader as TranslateLoaderService;

        this.defaultLang = 'en';
        this.translate.setFallbackLang(this.defaultLang);
        this.customLoader.setDefaultLang(this.defaultLang);

        if (this.providers && this.providers.length > 0) {
            for (const provider of this.providers) {
                this.addTranslationFolder(provider.name, provider.source);
            }
        }

        // Try to read locale from storage synchronously to apply it before components render
        const storedLocale = this.userPreferencesService.get(UserPreferenceValues.Locale);

        if (storedLocale) {
            // Apply stored locale immediately during construction
            this.userLang = storedLocale;
            this.loadTranslation(storedLocale, this.defaultLang);
        }

        effect(() => {
            const locale = this.userPreferencesService.localeSignal();

            if (locale && locale !== this.userLang) {
                this.userLang = locale;
                this.loadTranslation(locale, this.defaultLang);
            }
        });
    }

    /**
     * Adds a new folder of translation source files.
     *
     * @param name Name for the translation provider
     * @param path Path to the folder
     */
    addTranslationFolder(name: string = '', path: string = '') {
        if (!this.customLoader.providerRegistered(name)) {
            this.customLoader.registerProvider(name, path);

            if (this.userLang) {
                this.loadTranslation(this.userLang, this.defaultLang);
            } else {
                this.loadTranslation(this.defaultLang);
            }
        }
    }

    /**
     * Loads a translation file.
     *
     * @param lang Language code for the language to load
     * @param fallback Language code to fall back to if the first one was unavailable
     */
    loadTranslation(lang: string, fallback?: string) {
        this.translate.currentLoader.getTranslation(lang).subscribe(
            () => {
                this.translate.use(lang);
                this.onTranslationChanged(lang);
            },
            () => {
                if (fallback && fallback !== lang) {
                    this.loadTranslation(fallback);
                }
            }
        );
    }

    /**
     * Triggers a notification callback when the translation language changes.
     *
     * @param lang The new language code
     */
    onTranslationChanged(lang: string): void {
        const translations = this.customLoader.getFullTranslationJSON?.(lang) ?? {};
        this.translate.setTranslation(lang, translations, true);
    }

    /**
     * Sets the target language for translations.
     *
     * @param lang Code name for the language
     * @returns Translations available for the language
     */
    use(lang: string): Observable<any> {
        this.customLoader.init(lang);
        return this.translate.use(lang);
    }

    /**
     * Gets the translation for the supplied key.
     *
     * @param key Key to translate
     * @param interpolateParams String(s) to be interpolated into the main message
     * @returns Translated text
     */
    get(key: string | Array<string>, interpolateParams?: any): Observable<string | any> {
        return this.translate.get(key, interpolateParams);
    }

    /**
     * Determines the preferred locale for the current user.
     *
     * @returns Locale identifier resolved from the browser or the default translation locale
     */
    getLocale(): string {
        const defaultLocale = this.userLang || this.defaultLang;
        if (typeof window?.navigator === 'undefined') {
            return defaultLocale;
        }
        const wn = window.navigator as Navigator;
        let lang = wn.languages ? wn.languages[0] : defaultLocale;
        lang = lang || wn.language;
        return lang;
    }

    /**
     * Directly returns the translation for the supplied key.
     *
     * @param key Key to translate
     * @param interpolateParams String(s) to be interpolated into the main message
     * @returns Translated text
     */
    instant(key: string | Array<string>, interpolateParams?: any): string | any {
        return key ? this.translate.instant(key, interpolateParams) : '';
    }
}
