export const NOTIFICATION_TYPE = {
    INFO: 'info',
    WARN: 'warning',
    ERROR: 'error',
    RECURSIVE: 'recursive'
} as const;

export type NOTIFICATION_TYPE = (typeof NOTIFICATION_TYPE)[keyof typeof NOTIFICATION_TYPE];

export interface NotificationInitiator {
    key: string | symbol;
    displayName: string;
    firstName?: string;
    lastName?: string;
    extra?: any;
}

export interface NotificationModel {
    type: NOTIFICATION_TYPE;
    initiator: NotificationInitiator;
    datetime: Date;
    messages: string[];
    icon?: string;
    clickCallBack?: any;
    args?: any;
}
