import { TemplateRef, Type } from '@angular/core';
import { Subject } from 'rxjs';
import { DialogSizes } from './dialog.model';

export interface DialogData {
    title: string;
    description?: string;
    confirmButtonTitle?: string;
    cancelButtonTitle?: string;
    isConfirmButtonDisabled$?: Subject<boolean>;
    isCloseButtonHidden?: boolean;
    isCancelButtonHidden?: boolean;
    dialogSize?: DialogSizes;
    contentText?: string;
    contentComponent?: Type<any>;
    contentTemplate?: TemplateRef<any>;
    actionsTemplate?: TemplateRef<any>;
    descriptionTemplate?: TemplateRef<any>;
    headerIcon?: string;
    additionalActionButtons?: AdditionalDialogActionButton[];
    componentData?: any;
    dataOnConfirm$?: Subject<any>;
}

export interface AdditionalDialogActionButton {
    title: string;
    onClick: (args?: any) => void;
    class?: string;
}
